\documentclass[11pt]{article}
\usepackage[margin=2.5cm]{geometry}
\usepackage{booktabs}

\title{Barrel-Ageing Trials: Phenolic Panel at Spring Rackings}
\author{Cellar Team, Domaine de la Combe}
\date{March 2026}

\begin{document}
\maketitle

The phenolic panel tracks the three trial lots through the
second racking. Table~\ref{tab:phenolic} reports the mean of
duplicate measurements taken at the spring rackings, before any
blending trials begin.

\begin{table}[htbp]
\centering
\caption{Mean phenolic measurements for the 2024 trial lots.}
\label{tab:phenolic}
\begin{tabular}{lcc}
\toprule
Lot & Anthocyanins (mg/L) & Tannin (g/L) \\
\midrule
Merlot A & 412.5 & 2.4 \\
Merlot B & 388 & 2.15 \\
Syrah C & 455.25 & 2.8 \\
\bottomrule
\end{tabular}
\end{table}

Blending decisions for the final cuv\'ee will be minuted after
the July tasting panel, once the malolactic notes are in.

\end{document}

